#### Phase 3: Integration with Product

9. **Create Rule-Based Extension Base Class**:
   ```csharp
   public abstract class RuleBasedExtension<TInput, TOutput>
   {
       protected readonly RulesEngine _rulesEngine;
       protected readonly IRuleRepository _ruleRepository;
       protected readonly string _workflowName;

       protected RuleBasedExtension(
           IRuleRepository ruleRepository,
           string workflowName)
       {
           _ruleRepository = ruleRepository;
           _workflowName = workflowName;
       }

       protected async Task InitializeRulesAsync(string tenantId)
       {
           var rules = await _ruleRepository.GetRulesAsync(_workflowName, tenantId);
           var workflow = new Workflow
           {
               WorkflowName = _workflowName,
               Rules = rules
           };
           _rulesEngine = new RulesEngine(new[] { workflow }, null);
       }

       protected async Task<List<RuleResultTree>> EvaluateRulesAsync(TInput input)
       {
           var ruleParam = new RuleParameter("input", input);
           return await _rulesEngine.ExecuteAllRulesAsync(_workflowName, ruleParam);
       }

       public abstract Task<TOutput> ExecuteAsync(TInput input);
   }
   ```

10. **Implement State-Specific Extension**:
    ```csharp
    public class FloridaEligibilityExtension : RuleBasedExtension<EligibilityRequest, EligibilityResult>
    {
        public FloridaEligibilityExtension(IRuleRepository repository)
            : base(repository, "FloridaEligibilityRules")
        {
            InitializeRulesAsync("Florida").Wait();
        }

        public override async Task<EligibilityResult> ExecuteAsync(EligibilityRequest request)
        {
            var ruleResults = await EvaluateRulesAsync(request);

            // Check for errors
            var errors = ruleResults
                .Where(r => !r.IsSuccess && r.Rule.ErrorType == "Error")
                .Select(r => r.ExceptionMessage)
                .ToList();

            if (errors.Any())
                return EligibilityResult.Denied(errors);

            // Check for warnings
            var warnings = ruleResults
                .Where(r => !r.IsSuccess && r.Rule.ErrorType == "Warning")
                .Select(r => r.ExceptionMessage)
                .ToList();

            // Determine eligibility category
            var category = DetermineEligibilityCategory(ruleResults);

            return EligibilityResult.Approved(category, warnings);
        }

        private string DetermineEligibilityCategory(List<RuleResultTree> results)
        {
            // Check which approval rule succeeded
            var approvalRule = results.FirstOrDefault(r =>
                r.IsSuccess && r.Rule.RuleName.StartsWith("Approve_"));
            return approvalRule?.Rule.RuleName.Replace("Approve_", "") ?? "Standard";
        }
    }
    ```

11. **Add Rule Execution Monitoring**:
    ```csharp
    public class RuleExecutionMonitor
    {
        private readonly ILogger<RuleExecutionMonitor> _logger;

        public async Task<TResult> MonitoredExecutionAsync<TResult>(
            string ruleName,
            Func<Task<TResult>> ruleExecution)
        {
            var stopwatch = Stopwatch.StartNew();
            try
            {
                var result = await ruleExecution();
                stopwatch.Stop();

                _logger.LogInformation(
                    "Rule {RuleName} executed in {ElapsedMs}ms",
                    ruleName, stopwatch.ElapsedMilliseconds);

                return result;
            }
            catch (Exception ex)
            {
                stopwatch.Stop();
                _logger.LogError(ex,
                    "Rule {RuleName} failed after {ElapsedMs}ms",
                    ruleName, stopwatch.ElapsedMilliseconds);
                throw;
            }
        }
    }
    ```

