#### Example 3: Rule Composition in Code

```csharp
public class MichiganProviderEnrollmentRules
{
    public IRule<Provider> BuildEnrollmentRules()
    {
        // Individual rules
        var licenseValid = new Rule<Provider>("LicenseValid",
            p => p.LicenseExpiration > DateTime.Today,
            "Provider license has expired");

        var backgroundCheckClear = new Rule<Provider>("BackgroundCheck",
            p => p.BackgroundCheckStatus == "Clear",
            "Background check not cleared");

        var liabilityInsuranceCurrent = new Rule<Provider>("Insurance",
            p => p.LiabilityInsuranceExpiration > DateTime.Today.AddDays(30),
            "Liability insurance expired or expiring soon");

        var noSanctions = new Rule<Provider>("NoSanctions",
            p => !p.HasActiveSanctions,
            "Provider has active sanctions");

        // Compose with AND logic
        return licenseValid
            .And(backgroundCheckClear)
            .And(liabilityInsuranceCurrent)
            .And(noSanctions);
    }
}
```

