### Real-World Example 1: Medicaid Eligibility Rules

**Context**: Ohio Medicaid has complex eligibility determination rules that change frequently based on federal and state regulations. Different applicant categories (children, pregnant women, adults, disabled) have different income thresholds and criteria.

**Implementation**:

```json
{
  "WorkflowName": "OhioMedicaidEligibility",
  "Rules": [
    {
      "RuleName": "Approve_PregnantWomen",
      "SuccessEvent": "Approved:PregnantWomen:200%FPL",
      "RuleExpressionType": "LambdaExpression",
      "Expression": "input.IsPregnant == true && input.HouseholdIncome <= (input.FederalPovertyLevel * 2.00) && input.OhioResident == true",
      "Actions": {
        "OnSuccess": {
          "Category": "PregnantWomen",
          "CoverageStartDate": "FirstDayOfNextMonth"
        }
      }
    },
    {
      "RuleName": "Approve_ChildrenUnder6",
      "SuccessEvent": "Approved:Children:216%FPL",
      "Expression": "input.Age < 6 && input.HouseholdIncome <= (input.FederalPovertyLevel * 2.16)",
      "Actions": {
        "OnSuccess": {
          "Category": "CHIP",
          "TierLevel": "Enhanced"
        }
      }
    },
    {
      "RuleName": "Approve_Children6to18",
      "SuccessEvent": "Approved:Children:206%FPL",
      "Expression": "input.Age >= 6 && input.Age < 19 && input.HouseholdIncome <= (input.FederalPovertyLevel * 2.06)"
    },
    {
      "RuleName": "Approve_Adults",
      "SuccessEvent": "Approved:Adults:138%FPL",
      "Expression": "input.Age >= 19 && input.Age < 65 && input.HouseholdIncome <= (input.FederalPovertyLevel * 1.38) && input.NotEligibleForMedicare == true"
    },
    {
      "RuleName": "Approve_Disabled_SSI",
      "SuccessEvent": "Approved:Disabled:SSI",
      "Expression": "input.ReceivesSSI == true",
      "Actions": {
        "OnSuccess": {
          "Category": "Disabled",
          "AutoEnroll": true
        }
      }
    },
    {
      "RuleName": "Deny_IncomeExceeded",
      "ErrorMessage": "Household income exceeds eligibility threshold for all categories",
      "ErrorType": "Error",
      "Expression": "input.HouseholdIncome > (input.FederalPovertyLevel * 2.16)"
    },
    {
      "RuleName": "Deny_NonResident",
      "ErrorMessage": "Applicant must be an Ohio resident",
      "ErrorType": "Error",
      "Expression": "input.OhioResident == false"
    },
    {
      "RuleName": "Deny_UndocumentedIneligible",
      "ErrorMessage": "Immigration status does not qualify for Ohio Medicaid",
      "ErrorType": "Error",
      "Expression": "input.DocumentedStatus == false && input.Age >= 19"
    }
  ]
}
```

**Extension Code**:

```csharp
public class OhioEligibilityExtension : IEligibilityDetermination
{
    private readonly RulesEngine _rulesEngine;
    private readonly IFederalPovertyLevelService _fplService;

    public OhioEligibilityExtension(IRuleRepository ruleRepository, IFederalPovertyLevelService fplService)
    {
        var rules = ruleRepository.GetRulesAsync("OhioMedicaidEligibility", "Ohio").Result;
        var workflow = new Workflow { WorkflowName = "OhioMedicaidEligibility", Rules = rules };
        _rulesEngine = new RulesEngine(new[] { workflow }, null);
        _fplService = fplService;
    }

    public async Task<EligibilityResult> DetermineEligibilityAsync(EligibilityApplication application)
    {
        // Enrich application with FPL data
        var fpl = await _fplService.GetFederalPovertyLevelAsync(
            application.HouseholdSize,
            DateTime.Today.Year);

        var input = new
        {
            application.Age,
            application.IsPregnant,
            application.HouseholdIncome,
            FederalPovertyLevel = fpl,
            application.OhioResident,
            application.ReceivesSSI,
            application.NotEligibleForMedicare,
            application.DocumentedStatus
        };

        var ruleParam = new RuleParameter("input", input);
        var results = await _rulesEngine.ExecuteAllRulesAsync("OhioMedicaidEligibility", ruleParam);

        // Check for denials (errors)
        var denials = results
            .Where(r => !r.IsSuccess && r.Rule.ErrorType == "Error")
            .Select(r => r.Rule.ErrorMessage)
            .ToList();

        if (denials.Any())
        {
            return EligibilityResult.Denied(
                reasons: denials,
                appealRights: GetAppealRightsInformation());
        }

        // Find approval rule
        var approval = results.FirstOrDefault(r =>
            r.IsSuccess && r.Rule.SuccessEvent.StartsWith("Approved:"));

        if (approval != null)
        {
            var eventParts = approval.Rule.SuccessEvent.Split(':');
            return EligibilityResult.Approved(
                category: eventParts[1],
                incomeThreshold: eventParts[2],
                effectiveDate: CalculateEffectiveDate(approval));
        }

        return EligibilityResult.PendingReview(
            reason: "Application requires manual review");
    }
}
```

**Test Results**:

```
Test Case 1: Pregnant Woman, Income = $30,000, FPL = $20,000 (150% FPL)
  Rule Evaluated: Approve_PregnantWomen
  Result: APPROVED ✅
  Category: PregnantWomen
  Income Threshold: 200% FPL
  Coverage Start: 2024-03-01

Test Case 2: Child Age 4, Income = $45,000, FPL = $20,000 (225% FPL)
